"""Reference Solution — Lab 07: Playwright UI Locator & Auto-Wait Poll Engine."""
import time
from typing import Any, Callable, Dict, List


class RoleLocatorEngine:
    def validate_selector(self, selector: str) -> str:
        s = selector.strip()
        if s.startswith("//") or "nth-child" in s:
            raise ValueError(f"Brittle selector forbidden: {selector}")
        return s

    def get_by_role(self, dom_nodes: List[Dict[str, Any]], role: str, name: str) -> Dict[str, Any]:
        matches = [
            n for n in dom_nodes
            if n.get("visible", True)
            and str(n.get("role", "")).lower() == role.lower()
            and str(n.get("name", "")).strip().lower() == name.strip().lower()
        ]
        if len(matches) != 1:
            raise LookupError(f"Strict mode violation: found {len(matches)} nodes for role={role} name={name}")
        return matches[0]

    def expect_text_eventually(self, read_text: Callable[[], str], expected: str, timeout_s: float = 0.3) -> str:
        deadline = time.monotonic() + timeout_s
        last = ""
        while time.monotonic() <= deadline:
            last = read_text()
            if expected in last:
                return last
            time.sleep(0.015)
        raise AssertionError(f"Expected '{expected}' within {timeout_s}s, last='{last}'")

