"""Reference Solution — Lab 08: API Contract Schema Validator & Concierge Grounding Guard."""
import re
from typing import Any, Dict
from apps.aerocart.server import dispatch_request

VALID_STATUSES = {"PENDING_PAYMENT", "CONFIRMED"}
STOPWORDS = {"the", "and", "for", "with", "can", "are", "you", "under", "from", "that"}


def validate_order_contract(payload: Dict[str, Any]) -> bool:
    oid = payload.get("orderId")
    status = payload.get("status")
    seat = payload.get("seat")
    if not isinstance(oid, str) or not oid.strip():
        raise ValueError("Invalid orderId")
    if status not in VALID_STATUSES:
        raise ValueError(f"Unexpected order status: {status}")
    if not isinstance(seat, str) or not seat.strip():
        raise ValueError("Invalid seat")
    return True


def verify_concierge_grounding(query: str, mode: str = "grounded") -> bool:
    resp = dispatch_request("POST", "/api/v1/concierge/chat", body={"query": query, "mode": mode})
    if resp["status_code"] != 200:
        return False
    data = resp["data"]
    contexts = data.get("retrievedContexts") or []
    answer = str(data.get("answer") or "").lower()
    if not contexts or "no restrictions" in answer or "at any time before" in answer:
        return False
    ctx_tokens = {w for w in re.findall(r"[a-z0-9]+", contexts[0].lower()) if len(w) >= 3 and w not in STOPWORDS}
    ans_tokens = {w for w in re.findall(r"[a-z0-9]+", answer) if len(w) >= 3 and w not in STOPWORDS}
