"""Reference Solution — Lab 09: Reverse-Dependency Test Impact Analysis (TIA) Graph."""
from collections import defaultdict, deque
from typing import Dict, List, Set


def select_impacted_tests(
    dep_graph: Dict[str, List[str]],
    changed_files: List[str],
    global_triggers: Set[str],
) -> List[str]:
    all_tests = sorted(n for n in dep_graph if n.startswith("test_"))
    if any(f in global_triggers for f in changed_files):
        return all_tests

    rev: Dict[str, List[str]] = defaultdict(list)
    for caller, imports in dep_graph.items():
        for imp in imports:
            rev[imp].append(caller)

    seen = set(changed_files)
    q = deque(changed_files)
    while q:
        curr = q.popleft()
        for caller in rev.get(curr, []):
            if caller not in seen:
                seen.add(caller)
                q.append(caller)
    return sorted(n for n in seen if n.startswith("test_"))

"""Reference Solution — Lab 11: Dockerfile Cache Auditor & K8s OOMKilled (Exit 137) Guard."""
from typing import Any, Dict, List


def audit_container_spec(
    dockerfile_lines: List[str],
    pod_limit_mb: int,
    jvm_heap_mb: int,
) -> Dict[str, Any]:
    findings: List[str] = []
    copy_all_idx = -1
    install_idx = -1
    for idx, raw in enumerate(dockerfile_lines):
        ln = raw.strip()
        if ln.upper().startswith("FROM ") and ":latest" in ln.lower():
            findings.append("FLOATING_TAG")
        if ln.startswith("COPY . ") or ln == "COPY . .":
            if copy_all_idx == -1:
                copy_all_idx = idx
        if any(cmd in ln for cmd in ("pip install", "npm ci", "mvn dependency:go-offline")):
            install_idx = idx
    if copy_all_idx != -1 and install_idx != -1 and copy_all_idx < install_idx:
        findings.append("CACHE_BUST")
    if jvm_heap_mb > pod_limit_mb * 0.75:
        findings.append("OOM_RISK_137")
    return {"passed": len(findings) == 0, "findings": findings}

