"""Reference Solution — Lab 13: BOLA Tenant Guard, JWT `alg:none` Verifier & Prompt Shield."""
from typing import Any, Dict

ALLOWED_ALGS = {"HS256", "RS256", "ES256"}
INJECTION_SIGNATURES = (
    "ignore previous instructions",
    "disregard all prior",
    "reveal system prompt",
    "print api_key",
    "dump environment variables",
)


def authorize_order_access(
    jwt_header: Dict[str, Any],
    jwt_claims: Dict[str, Any],
    resource_owner_tenant: str,
    now_ts: int = 1700000000,
) -> int:
    alg = str(jwt_header.get("alg") or "")
    if alg not in ALLOWED_ALGS:
        return 401
    exp = int(jwt_claims.get("exp") or 0)
    if exp <= now_ts:
        return 401
    caller_tenant = str(jwt_claims.get("tenant_id") or "")
    if not caller_tenant or caller_tenant != resource_owner_tenant:
        return 403
    return 200


def scan_prompt_injection(user_prompt: str) -> Dict[str, Any]:
    low = user_prompt.lower()
    for sig in INJECTION_SIGNATURES:
        if sig in low:
            return {"blocked": True, "reason": f"Matched injection signature: {sig}"}
    return {"blocked": False, "reason": "clean"}
